import{V as a}from"./chunks/theme.Dnfezwhj.js";import{c as n,I as r,k as s,a4 as i,j as e,a as t,o as l}from"./chunks/framework.BgUgRheH.js";const h=i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Hi everyone 👋,<br> I am <a href="https://github.com/coorasse" target="_blank" rel="noreferrer">Alessandro</a>, the maintainer of CanCanCan since 2015. I want to present you this new guide for developers.</p><p>Since I took over the CanCanCan project in 2015, I felt one of the most urgent things to do was rewriting the documentation: the previous documentation was in a Wiki, but giving free access to everyone to edit it, ended up in a big mess after so many years. <strong>Information was all there, but in a very unstructured way.</strong></p><p>One of the first things I did was to block the Wiki from free editing and after that, I moved all the wiki within the git repository, so that every update had to go through a Pull Request and code review.</p><p><strong>I think documentation is as important as the source code, and therefore should follow the same approval process of the code.</strong></p><p>After one year from this decision, I realised that this was not sufficient: I still didn&#39;t like the status of the documentation, and I had to explain too often to my colleagues at <a href="https://renuo.ch" target="_blank" rel="noreferrer">Renuo</a> the basic mechanisms of this library. And all my colleagues are all very smart people!! So I understood that we were still missing a well structured developer documentation.</p><p>I hope you&#39;ll appreciate this work and you&#39;ll now be able to use CanCanCan at it&#39;s maximum potential.</p><p>I suggest also experienced CanCanCan developers to read it, since you might find out interesting features that have been recently introduced and you might not be aware of, since they were not previously documented.</p><p>Thanks again to all my sponsors, who allowed me to take the time to properly write this documentation, and thanks to all the contributors for your help with this wonderful library ❤️.</p><p>If you&#39;d like to sponsor this library, head to <a href="https://github.com/sponsors/coorasse" target="_blank" rel="noreferrer">https://github.com/sponsors/coorasse</a>. It means a lot.</p><p>Thank you,</p>',11),d=e("p",null,[t("Head to the "),e("a",{href:"./installation"},"Installation"),t(" chapter.")],-1),_=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1716469822000}'),c={name:"introduction.md"},b=Object.assign(c,{setup(u){const o=[{avatar:"https://avatars.githubusercontent.com/u/1319150",name:"Alessandro Rodi",title:"Maintainer",sponsor:"https://github.com/sponsors/coorasse",links:[{icon:"github",link:"https://github.com/coorasse"},{icon:"twitter",link:"https://twitter.com/coorasse"}]}];return(p,m)=>(l(),n("div",null,[h,r(s(a),{size:"small",members:o}),d]))}});export{_ as __pageData,b as default};
